    return (False, None)
p = assign['alpha']
t = assign['t']
# Basic validations
if not is_int(p) or not is_int(t):
    return (False, None)
if t < 2:
    return (False, None)
if not is_prime(p):
    return (False, None)
# Build the answer string using precise classification.
# Classification:
# Let a <= b and t >= 2.
# Case 1: p = 2.
#   (i) a = b and a + 1 is divisible by t (i.e., a = t*u - 1 for u >= 1).
#   (ii) If t = 2, also a even (a = 2*u, u >= 0) and b = a + 3.
# Case 2: p odd.
#   Solutions exist iff p + 1 = 2^t (i.e., p = 2^t - 1), in which case a = t*u, b = a + 1 for u >= 0.
#   Otherwise, no solutions.
def build_answer(p, t):
